#include "AIE2PLegalizerInfo.h"
#include "AIE2PSubtarget.h"
#include "llvm/CodeGen/GlobalISel/GenericMachineInstrs.h"
#include "llvm/CodeGen/GlobalISel/LegalizerInfo.h"
#include "llvm/CodeGen/TargetOpcodes.h"
#include "llvm/Support/MathExtras.h"

using namespace llvm;
using namespace LegalityPredicates;

static LegalityPredicate isLegalBitCastType(unsigned TypeIdx) {
  return [=](const LegalityQuery &Query) {
    LLT Ty = Query.Types[TypeIdx];
    const unsigned TypeSize = Ty.getSizeInBits();
    if (Ty.isScalar())
      return TypeSize >= 32;
    const unsigned EltSize = Ty.getElementType().getSizeInBits();
    return TypeSize == 32 || TypeSize == 64 ||
           (EltSize >= 8 && isPowerOf2_32(EltSize));
  };
}

static LegalizeMutation bitcastAccToVectorType(unsigned TypeIdx) {
  return [=](const LegalityQuery &Query) {
    LLT OrigTy = Query.Types[TypeIdx];
    assert(OrigTy.getElementType() == LLT::scalar(64) &&
           "Expected an accumulator type");
    unsigned Size = OrigTy.getSizeInBits();
    assert(Size % 32 == 0);
    return std::pair(TypeIdx, LLT::fixed_vector(Size / 32, 32));
  };
}

static LegalizeMutation bitcastToVectorElement32(const unsigned TypeIdx) {
  return [=](const LegalityQuery &Query) {
    const LLT Ty = Query.Types[TypeIdx];
    unsigned Size = Ty.getSizeInBits();
    assert(Size % 32 == 0);
    return std::pair(
        TypeIdx, LLT::scalarOrVector(ElementCount::getFixed(Size / 32), 32));
  };
}

static LegalityPredicate
isValidVectorMergeUnmergeOp(const unsigned BigVectorId,
                            const unsigned SmallVectorId) {
  return [=](const LegalityQuery &Query) {
    const LLT Big = Query.Types[BigVectorId];
    const LLT Small = Query.Types[SmallVectorId];
    return Big.isVector() && Small.isVector() &&
           Big.getElementType() == Small.getElementType() &&
           Small.getNumElements() * 2 == Big.getNumElements();
  };
}

static LegalityPredicate isValidVectorAIEP(const unsigned TypeIdx) {
  return [=](const LegalityQuery &Query) {
    const LLT DstTy = Query.Types[TypeIdx];
    const unsigned DstSize = DstTy.getSizeInBits();
    return DstTy.isVector() && (DstSize == 32 || DstSize > 64);
  };
}

static LegalityPredicate
negatePredicate(const std::function<bool(const LegalityQuery &)> &Func) {
  return [=](const LegalityQuery &Query) { return !Func(Query); };
}

static bool isVectorRegisterSized(const LLT &Ty) {
  const unsigned Size = Ty.getSizeInBits();
  return Size == 256 || Size == 512 || Size == 1024 || Size == 2048;
}

static LegalityPredicate vectorSmallerThan(unsigned TypeIdx, unsigned Size) {
  return [=](const LegalityQuery &Query) {
    const LLT QueryTy = Query.Types[TypeIdx];
    return QueryTy.isVector() && QueryTy.getSizeInBits() < Size;
  };
}

static const LLT P0 = LLT::pointer(0, 20);

static const LLT S8 = LLT::scalar(8);
static const LLT S16 = LLT::scalar(16);
static const LLT S20 = LLT::scalar(20);
static const LLT S32 = LLT::scalar(32);
static const LLT S64 = LLT::scalar(64);
static const LLT S128 = LLT::scalar(128);
static const LLT S256 = LLT::scalar(256);
static const LLT S512 = LLT::scalar(512);
static const LLT S1024 = LLT::scalar(1024);

// 16-bit vectors
static const LLT V16S1 = LLT::fixed_vector(16, 1);
static const LLT V2S8 = LLT::fixed_vector(2, 8);

// 32-bit vectors
static const LLT V32S1 = LLT::fixed_vector(32, 1);
static const LLT V4S8 = LLT::fixed_vector(4, 8);
static const LLT V2S16 = LLT::fixed_vector(2, 16);

// 64-bit vectors
static const LLT V2S32 = LLT::fixed_vector(2, 32);
static const LLT V4S16 = LLT::fixed_vector(4, 16);
static const LLT V8S8 = LLT::fixed_vector(8, 8);
static const LLT V64S1 = LLT::fixed_vector(64, 1);

// 128-bit vectors
static const LLT V16S8 = LLT::fixed_vector(16, 8);
static const LLT V8S16 = LLT::fixed_vector(8, 16);
static const LLT V4S32 = LLT::fixed_vector(4, 32);

// 256-bit vectors
static const LLT V32S8 = LLT::fixed_vector(32, 8);
static const LLT V16S16 = LLT::fixed_vector(16, 16);
static const LLT V8S32 = LLT::fixed_vector(8, 32);

// 256-bit accumulators
static const LLT AccV8S32 = LLT::fixed_vector(8, 32);
static const LLT AccV4S64 = LLT::fixed_vector(4, 64);

static const LLT V2S128 = LLT::fixed_vector(2, S128);

// 512-bit vectors
static const LLT V16S32 = LLT::fixed_vector(16, 32);
static const LLT V32S16 = LLT::fixed_vector(32, 16);
static const LLT V64S8 = LLT::fixed_vector(64, 8);
static const LLT V2S256 = LLT::fixed_vector(2, 256);

// 512-bit accumulators
static const LLT AccV1632 = LLT::fixed_vector(16, 32);
static const LLT AccV8S64 = LLT::fixed_vector(8, 64);

// 1024-bit vectors
static const LLT V32S32 = LLT::fixed_vector(32, 32);
static const LLT V64S16 = LLT::fixed_vector(64, 16);
static const LLT V128S8 = LLT::fixed_vector(128, 8);
static const LLT V2S512 = LLT::fixed_vector(2, 512);

// 1024-bit accumulators
static const LLT AccV32S32 = LLT::fixed_vector(32, 32);
static const LLT AccV16S64 = LLT::fixed_vector(16, 64);

// 2048-bit accumulators
static const LLT AccV64S32 = LLT::fixed_vector(64, 32);
static const LLT AccV32S64 = LLT::fixed_vector(32, 64);
static const LLT AccV2S1024 = LLT::fixed_vector(2, 1024);

static const std::initializer_list<LLT> AIE2PVectorTypes = {
    /* Begin 32-bit types*/
    V4S8, V2S16,
    /* Begin 256-bit types */
    V8S32, V16S16, V32S8,
    /* Begin 512-bit types */
    V16S32, V32S16, V64S8,
    /* Begin 1024-bit types */
    V32S32, V64S16, V128S8};

static const std::initializer_list<LLT> AIE2PAccumulatorTypes = {
    /* Begin 256-bit types */
    AccV8S32, AccV4S64,
    /* Begin 512-bit types */
    AccV1632, AccV8S64,
    /* Begin 1024-bit types */
    AccV32S32, AccV16S64,
    /* Begin 2048-bit types */
    AccV64S32, AccV32S64};

AIE2PLegalizerInfo::AIE2PLegalizerInfo(const AIE2PSubtarget &ST)
    : AIEHelper(ST) {
  using namespace TargetOpcode;

  getActionDefinitionsBuilder({G_IMPLICIT_DEF, G_FREEZE})
      .legalFor({S20, S32, P0, S128, S256, S512, S1024, V4S32, V8S16, V16S8,
                 V2S32, V4S16, V8S8, V32S1})
      .legalFor(AIE2PVectorTypes)
      .legalFor(AIE2PAccumulatorTypes)
      .legalFor({AccV2S1024})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32);

  getActionDefinitionsBuilder(G_CONSTANT)
      .legalFor({S20, S32, P0})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32);

  getActionDefinitionsBuilder(G_FCONSTANT).customFor({S16, S32, S64});

  getActionDefinitionsBuilder(G_ICMP)
      .legalFor({{S32, S32}, {S32, P0}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32)
      .customFor({{V32S1, V32S16}, {V64S1, V64S8}, {V16S1, V16S32}});

  getActionDefinitionsBuilder(G_FCMP)
      .clampScalar(0, S32, S32)
      .customFor({{S32, S16}, {S32, S32}, {S32, S64}});

  getActionDefinitionsBuilder(G_FPTRUNC)
      .libcallFor({{S32, S64}})
      .customFor({{S16, S32}});

  getActionDefinitionsBuilder({G_SITOFP, G_UITOFP})
      .libcallForCartesianProduct({S32, S64})
      .clampScalar(1, S32, S64)
      .widenScalarToNextPow2(1)
      .clampScalar(0, S32, S64);

  getActionDefinitionsBuilder(G_FPEXT)
      .libcallFor({{S64, S32}})
      .customFor({{S32, S16}})
      .narrowScalarFor({{S64, S16}}, llvm::LegalizeMutations::changeTo(0, S32));

  getActionDefinitionsBuilder({G_FPTOSI, G_FPTOUI})
      .libcallForCartesianProduct({S32, S64})
      .clampScalar(0, S32, S64)
      .widenScalarToNextPow2(0)
      .clampScalar(1, S32, S64);

  getActionDefinitionsBuilder(G_FABS).customFor({S16, S32, S64}).scalarize(0);

  getActionDefinitionsBuilder(G_FMUL)
      .legalFor({V64S16, V32S16})
      // We don't have an instruction to multiply bf16 scalars, so instead of
      // using an inefficient and potentially unsafe libcall (e.g. in the case
      // of hardware loops) we need custom legalization by inserting the bf16
      // scalar into a vector, perform the element wise multiplication with
      // VMUL.f and extract the bf16 scalar again.
      .customFor({S16})
      .libcallFor({S32, S64});

  getActionDefinitionsBuilder({G_FADD, G_FSUB})
      .legalFor({AccV64S32})
      .clampScalar(0, S32, S64)
      .customFor({S32})
      .libcallFor({S64});

  getActionDefinitionsBuilder({G_FDIV, G_FREM})
      .clampScalar(0, S32, S64)
      .libcallFor({S32, S64});

  // Since the only integers smaller than 32 bits we produce are S20 (from
  // G_PTRTOINT), the only legal extension is S20 -> S32.
  // Extensions to types larger than 64 bits have to be broken down into
  // multiple parts. We also explicitly mark S16 -> S32 ZEXT as artificially
  // legal because of G_ICMP, but this operation is removed by
  // postlegalizer combiner.
  getActionDefinitionsBuilder(G_ZEXT)
      .legalFor({{S32, S20}, {S32, S16}})
      .clampScalar(0, S32, S32);

  getActionDefinitionsBuilder({G_ANYEXT, G_SEXT})
      .legalFor({{S32, S20}})
      .clampScalar(0, S32, S32);
  // FIXME: (s|z|any)ext s20 to s64 is broken.

  getActionDefinitionsBuilder({G_AND, G_OR})
      .legalFor({S32, V2S16, V4S8})
      .legalFor(AIE2PVectorTypes)
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32)
      .scalarizeIf(typeIs(0, V2S32), 0)
      .fewerElementsIf(typeInSet(0, {V4S16, V8S8}),
                       [=](const LegalityQuery &Query) {
                         const LLT &SrcTy = Query.Types[0];
                         return std::make_pair(
                             0, LLT::fixed_vector(SrcTy.getNumElements() / 2,
                                                  SrcTy.getElementType()));
                       });

  getActionDefinitionsBuilder(G_SEXT_INREG).custom();

  getActionDefinitionsBuilder({G_ASHR, G_LSHR, G_SHL})
      .legalFor({{S32, S32}})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder(G_BITREVERSE)
      .lowerFor({S16, S32})
      .clampScalar(0, S32, S32);
  getActionDefinitionsBuilder(G_BSWAP).lower();

  getActionDefinitionsBuilder(G_TRUNC)
      .legalIf([=](const LegalityQuery &Query) {
        const LLT &SrcTy = Query.Types[1];
        const LLT &DstTy = Query.Types[0];
        return SrcTy.isVector() && DstTy.isVector() &&
               (SrcTy.getSizeInBits() == 512 ||
                SrcTy.getSizeInBits() == 1024) &&
               DstTy.getElementType().getSizeInBits() * 2 ==
                   SrcTy.getElementType().getSizeInBits();
      })
      .legalIf([=](const LegalityQuery &Query) {
        const LLT &SrcTy = Query.Types[1];
        const LLT &DstTy = Query.Types[0];
        return SrcTy.isScalar() && DstTy.isScalar();
      })
      .customIf([=](const LegalityQuery &Query) {
        const LLT &SrcTy = Query.Types[1];
        const LLT &DstTy = Query.Types[0];
        return SrcTy.isVector() && SrcTy.getSizeInBits() == 256 &&
               DstTy.getElementType().getSizeInBits() * 2 ==
                   SrcTy.getElementType().getSizeInBits();
      })
      .fewerElementsIf(
          [=](const LegalityQuery &Query) {
            const LLT &SrcTy = Query.Types[1];
            return SrcTy.isVector() && SrcTy.getSizeInBits() == 2048;
          },
          [=](const LegalityQuery &Query) {
            const LLT &SrcTy = Query.Types[1];
            return std::make_pair(1,
                                  LLT::fixed_vector(SrcTy.getNumElements() / 2,
                                                    SrcTy.getElementType()));
          });

  getActionDefinitionsBuilder(G_SELECT)
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            const LLT &ResTy = Query.Types[0];
            return ResTy.isVector() && ResTy.getSizeInBits() == 32;
          },
          [=](const LegalityQuery &Query) {
            return std::pair(0, LLT::scalar(32));
          })
      .legalFor({{S32, S32}, {P0, S32}})
      .clampScalar(1, S32, S32)
      // AIE2P ISA supports only 512-bit vector select
      .legalFor({V16S32, V32S16, V64S8})
      // For scalar types >= 256, bitcast to a vector type and use existing
      // selection patterns
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            const LLT &ResTy = Query.Types[0];
            return ResTy.isScalar() && ResTy.getSizeInBits() >= 256;
          },
          [=](const LegalityQuery &Query) {
            const LLT Ty = Query.Types[0];
            const unsigned Size = Ty.getSizeInBits();
            return std::pair(0, LLT::fixed_vector(Size / 32, LLT::scalar(32)));
          })
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32)
      .fewerElementsIf(
          [=](const LegalityQuery &Query) {
            const LLT &DstTy = Query.Types[0];
            if (DstTy.getSizeInBits() == 64)
              return true;
            return false;
          },
          [=](const LegalityQuery &Query) {
            const LLT &DstTy = Query.Types[0];
            return std::make_pair(0,
                                  LLT::fixed_vector(DstTy.getNumElements() / 2,
                                                    DstTy.getElementType()));
          })
      .customIf(vectorSmallerThan(0, 512))
      // We support G_SELECT only on the vector register bank
      // Mapping the G_SELECT operands to the vector register bank
      // during register bank selection introduces the proper cross-bank
      // copies. However, we cannot write ISEL patterns expressing accumulator
      // types on vector register banks, which requires to duplicate the vector
      // type patterns in C++. Introducing bitcasts during legalization allows
      // to re-use the existing code for register bank selection and ISEL
      // patterns.
      .bitcastIf(typeInSet(0, {AccV4S64, AccV8S64, AccV16S64, AccV32S64}),
                 bitcastAccToVectorType(0))
      .clampMaxNumElements(0, S8, 64)
      .clampMaxNumElements(0, S16, 32)
      .clampMaxNumElements(0, S32, 16);

  getActionDefinitionsBuilder({G_ADD, G_SUB, G_XOR})
      .legalFor({S32})
      .legalFor({V16S32, V32S16, V64S8})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32)
      // AIE ISA supports only 512-bit vector add/sub/xor
      .clampMaxNumElements(0, S8, 64)
      .clampMaxNumElements(0, S16, 32)
      .clampMaxNumElements(0, S32, 16)
      // moreElements action could have used here, but it generate code more
      // like scalarization. We can use G_CONCAT_VECTORS and unmerge to do this
      // more optimally.
      .customIf(vectorSmallerThan(0, 512));

  // FIXME: G_SADDE/G_SSUBE doesn't support lowering. To support this properly,
  // the action needs to be implemented
  // FIXME: AIE2 has ADC and SBC operations to read the carry.
  getActionDefinitionsBuilder({G_UADDO, G_USUBO, G_UADDE, G_USUBE, G_SADDO,
                               G_SSUBO, G_SADDE, G_SSUBE, G_UADDSAT, G_USUBSAT,
                               G_SADDSAT, G_SSUBSAT})
      .lower();

  getActionDefinitionsBuilder(G_MUL)
      .legalFor({S32})
      .widenScalarToNextPow2(0)
      .minScalar(0, S32)
      .libcallFor({S64});

  // FIXME: G_SMULO, G_UMULO support
  getActionDefinitionsBuilder({G_UMULH, G_SMULH}).lower();

  getActionDefinitionsBuilder({G_SDIV, G_UDIV, G_SREM, G_UREM})
      .libcallFor({S32, S64})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S64);

  getActionDefinitionsBuilder({G_SDIVREM, G_UDIVREM})
      .lowerFor({S32, S64})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S64);

  getActionDefinitionsBuilder(G_ABS)
      .legalFor({S32})
      .lowerFor({S64})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32);

  // The CLZ instruction implements CTLZ, which also covers CTLZ_ZERO_UNDEF
  getActionDefinitionsBuilder(G_CTLZ_ZERO_UNDEF)
      .lowerFor({{S32, S32}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder(G_CTLZ)
      .legalFor({{S32, S32}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder(G_CTPOP)
      .legalFor({{S32, S32}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder(G_CTTZ_ZERO_UNDEF)
      .lowerFor({{S32, S32}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder(G_CTTZ)
      .lowerFor({{S32, S32}})
      .clampScalar(0, S32, S32)
      .clampScalar(1, S32, S32);

  getActionDefinitionsBuilder({G_FSHL, G_FSHR}).lower();

  getActionDefinitionsBuilder({G_ROTL, G_ROTR}).lower();

  getActionDefinitionsBuilder({G_MEMCPY, G_MEMSET, G_MEMMOVE})
      .customIf([=](const LegalityQuery &Query) {
        const LLT SizeArg = Query.Types[2];
        return SizeArg == S20;
      })
      .libcall();

  getActionDefinitionsBuilder(G_DYN_STACKALLOC).custom();
  getActionDefinitionsBuilder({G_STACKSAVE, G_STACKRESTORE}).lower();

  getActionDefinitionsBuilder({G_SMIN, G_SMAX, G_UMIN, G_UMAX})
      .widenScalarToNextPow2(0, 32)
      .lower();

  getActionDefinitionsBuilder({G_FRAME_INDEX, G_GLOBAL_VALUE}).legalFor({P0});

  getActionDefinitionsBuilder(G_INTTOPTR)
      .legalFor({{P0, S20}})
      .widenScalarToNextPow2(1)
      .clampScalar(1, S20, S20);

  getActionDefinitionsBuilder(G_PTRTOINT)
      .legalFor({{S20, P0}})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S20, S20);

  // We support pointer arithmetic on both GPRs (32-bits) and pointer regs
  // (20-bits, where the scalar addend resides in a MOD register). To allow
  // specifying alternative register bank mappings, we need to truncate the RHS
  // operand to 20-bits, thus we only allow s20 types for the scalar addend
  getActionDefinitionsBuilder(G_PTR_ADD)
      .legalFor({{P0, S20}})
      .widenScalarToNextPow2(1)
      .clampScalar(1, S20, S20);

  getActionDefinitionsBuilder({G_LOAD, G_STORE})
      .legalForTypesWithMemDesc({
          {S32, P0, S8, 8},
          {S32, P0, S16, 16},
          {S20, P0, S20, 32},
          {S32, P0, S32, 32},
          {P0, P0, S20, 32},
          {V16S8, P0, V16S8, 128},
          {V8S16, P0, V8S16, 128},
          {V4S32, P0, V4S32, 128},
          {V8S32, P0, V8S32, 256},
          {V16S16, P0, V16S16, 256},
          {V32S8, P0, V32S8, 256},
          {V16S32, P0, V16S32, 512},
          {V32S16, P0, V32S16, 512},
          {V64S8, P0, V64S8, 512},
          {V32S32, P0, V32S32, 512},
          {V64S16, P0, V64S16, 512},
          {V128S8, P0, V128S8, 512},
          {AccV4S64, P0, AccV4S64, 256},
          {AccV8S64, P0, AccV8S64, 512},
          {AccV16S64, P0, AccV16S64, 512},
          {AccV64S32, P0, AccV64S32, 512},
          {AccV32S64, P0, AccV32S64, 512},
          {S128, P0, S128, 128},
          {S256, P0, S256, 256},
      })
      // Legalize <2 x s1024>
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            return Query.Types[0] == AccV2S1024;
          },
          [=](const LegalityQuery &Query) { return std::pair(0, AccV32S64); })
      // Split 256-bit aligned load/store of 512-bit or larger vectors into
      // legal 256-bit loads with 32-byte alignment.
      .fewerElementsIf(
          [=](const LegalityQuery &Query) {
            const LLT &MemoryType = Query.MMODescrs[0].MemoryTy;
            const uint64_t Alignment = Query.MMODescrs[0].AlignInBits;
            unsigned MemSize = MemoryType.getSizeInBits();
            if (!MemoryType.isVector() || MemSize % 256 != 0)
              return false;
            // TODO: We could do the same as above for 16-byte aligned loads and
            // stores by splitting them into 128-bit loads and stores but this
            // doesn't work out of the box at the moment. We can easily enable
            // it later when we have a more complete legalizer and
            // regbankselect.
            return MemSize >= 512 && Alignment == 256;
          },
          [=](const LegalityQuery &Query) {
            const LLT &MemoryType = Query.MMODescrs[0].MemoryTy;
            const uint64_t Alignment = Query.MMODescrs[0].AlignInBits;
            const unsigned SplitFactor = MemoryType.getSizeInBits() / Alignment;
            return std::make_pair(
                0, LLT::fixed_vector(MemoryType.getNumElements() / SplitFactor,
                                     MemoryType.getElementType()));
          })
      // Storing a pointer/S20 to an un-aligned address.
      .customIf([=](const LegalityQuery &Query) {
        return AIEHelper.isUnaligned20BitStore(Query);
      })
      .widenScalarToNextPow2(0)
      .lowerIfMemSizeNotPow2()
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            const LLT &Ty = Query.Types[0];
            return Ty.isVector() &&
                   (Ty.getSizeInBits() == 64 || Ty.getSizeInBits() == 32);
          },
          [=](const LegalityQuery &Query) {
            const LLT Ty = Query.Types[0];
            const unsigned Size = Ty.getSizeInBits();
            assert(Size % 32 == 0);
            return std::pair(0, LLT::scalar(Size));
          })
      .clampScalar(0, S32, S32)
      .lower();

  getActionDefinitionsBuilder({G_ZEXTLOAD, G_SEXTLOAD})
      .legalForTypesWithMemDesc({{S32, P0, S8, 8}, {S32, P0, S16, 16}})
      .widenScalarToNextPow2(0)
      .lowerIfMemSizeNotPow2()
      .clampScalar(0, S32, S32)
      .lower();

  getActionDefinitionsBuilder(G_EXTRACT_VECTOR_ELT)
      .unsupportedIf([=](const LegalityQuery &Query) {
        const LLT &EltTy = Query.Types[1].getElementType();
        return Query.Types[0] != EltTy;
      })
      // Bitcast 32-bit vectors to 1 x s32, which will be expanded to bit
      // arithmetic
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            const LLT &VecTy = Query.Types[1];
            return VecTy.getSizeInBits() == 32;
          },
          bitcastToVectorElement32(1))
      // For 2 x 8 vectors, we want to increase the number of elements to 4
      .moreElementsIf(
          [=](const LegalityQuery &Query) {
            return Query.Types[1].getScalarSizeInBits() == 8 &&
                   Query.Types[1].getNumElements() == 2;
          },
          [=](const LegalityQuery &Query) {
            return std::make_pair(1, LLT::fixed_vector(4, S8));
          })
      // Custom legalize 2 x 32 vectors
      .customIf(typeInSet(1, {V2S32}))
      // Extend vectors to have at least 256-bits
      .clampMinNumElements(1, S8, 32)
      .clampMinNumElements(1, S16, 16)
      .clampMinNumElements(1, S32, 8)
      // Custom legalize resulting vector types >= 256-bit
      .customIf(typeIs(1, V2S128))
      .customIf(typeInSet(1, AIE2PVectorTypes))
      .customIf(typeInSet(1, AIE2PAccumulatorTypes))
      .customIf([=](const LegalityQuery &Query) {
        const LLT &VectTy = Query.Types[1];
        return VectTy.getElementType().getSizeInBits() >= 256;
      });

  getActionDefinitionsBuilder(G_INSERT_VECTOR_ELT)
      .clampScalar(2, S32, S32) // Clamp the idx to 32 bit since VINSERT
                                // relies on eR29 only for idx.
      // Custom legalize 2 x 32 vectors
      .customIf(typeInSet(0, {V2S32}))
      // Extend vectors to have at least 256-bits
      .clampMinNumElements(0, S8, 32)
      .clampMinNumElements(0, S16, 16)
      .clampMinNumElements(0, S32, 8)
      .clampMinNumElements(0, S64, 4)
      // Custom legalize resulting vector types >= 256-bit
      .customIf(typeInSet(0, AIE2PVectorTypes))
      .customIf(typeInSet(0, AIE2PAccumulatorTypes));

  // Control-flow
  getActionDefinitionsBuilder(G_BRCOND).legalFor({S32}).clampScalar(0, S32,
                                                                    S32);

  getActionDefinitionsBuilder(G_PHI)
      .legalFor({S20, S32, P0})
      .legalFor(AIE2PVectorTypes)
      .legalFor(AIE2PAccumulatorTypes)
      .legalFor({V16S8, V8S16, V4S32, V2S32, V4S16, V8S8})
      .widenScalarToNextPow2(0)
      .clampScalar(0, S32, S32);

  // We also explicitly mark V16S1 <-> S16 as artificially
  // legal because of G_ICMP, but this operation is removed by
  // postlegalizer combiner.
  getActionDefinitionsBuilder(G_BITCAST)
      .legalForCartesianProduct({S16, V16S1})
      .legalIf(
          LegalityPredicates::all(isLegalBitCastType(0), isLegalBitCastType(1)))
      .customIf(typeInSet(0, {V2S8, S16}));

  const LegalityPredicate IsNotValidDestinationVector =
      negatePredicate(isValidVectorAIEP(0));

  getActionDefinitionsBuilder(G_MERGE_VALUES)
      .legalFor({{S64, S32}})
      .customIf([=](const LegalityQuery &Query) {
        const LLT &DstTy = Query.Types[0];
        const LLT &SrcTy = Query.Types[1];

        if (!DstTy.isScalar() || DstTy.getSizeInBits() < 128)
          return false;

        const uint32_t DstSize = DstTy.getSizeInBits();
        const uint32_t SrcSize = SrcTy.getSizeInBits();

        if (!isPowerOf2_32(DstSize) || !isPowerOf2_32(SrcSize))
          return false;

        return (DstSize % SrcSize == 0);
      });

  getActionDefinitionsBuilder(G_UNMERGE_VALUES)
      .legalFor({{S32, S64},
                 {S32, V2S32},
                 {S256, V2S256},
                 {S512, V2S512},
                 {S1024, AccV2S1024}})
      .fewerElementsIf(
          [=](const LegalityQuery &Query) {
            const LLT &DstTy = Query.Types[0];
            const LLT &SrcTy = Query.Types[1];

            // Unmerge of sources <= 32-bit are legalized into bit arithmetic
            // below
            if (SrcTy.getSizeInBits() <= 32)
              return false;

            if (SrcTy.isVector() && DstTy.isScalar()) {
              // Unmerge results that are not vector register sized are
              // legalized to EXTRACT_VECTOR_ELT
              if (!isVectorRegisterSized(DstTy))
                return false;

              // Split unmerges with more than two scalar results into multiple
              // unmerges with two results
              return SrcTy.getNumElements() > 2;
            }

            if (SrcTy.isVector() && DstTy.isVector()) {
              // Unmerges into 2 subvectors are legal
              return !(2 * DstTy.getSizeInBits() == SrcTy.getSizeInBits());
            }

            return false;
          },
          [=](const LegalityQuery &Query) {
            const LLT &SrcTy = Query.Types[1];
            return std::make_pair(1,
                                  LLT::fixed_vector(SrcTy.getNumElements() / 2,
                                                    SrcTy.getElementType()));
          })
      .bitcastIf(
          [=](const LegalityQuery &Query) {
            const LLT &SrcTy = Query.Types[1];

            // If the source type is already a vector, there is nothing to do.
            return !SrcTy.isVector();
          },
          [=](const LegalityQuery &Query) {
            const LLT &DstTy = Query.Types[0];
            const LLT &SrcTy = Query.Types[1];
            const unsigned NumElems =
                SrcTy.getSizeInBits() / DstTy.getSizeInBits();
            return std::make_pair(1, LLT::fixed_vector(NumElems, DstTy));
          })
      .customIf([=](const LegalityQuery &Query) {
        const LLT &DstTy = Query.Types[0];
        const LLT &SrcTy = Query.Types[1];
        // Handle 2 cases
        // 1: vector of size 256 to 2 vectors of size 128
        // 2: Unmerge vector to scalar outputs
        return (DstTy.isVector() && SrcTy.getSizeInBits() == 256 &&
                DstTy.getSizeInBits() == 128) ||
               (SrcTy.isVector() && DstTy.isScalar() &&
                DstTy == SrcTy.getElementType());
      })
      .unsupportedIf(IsNotValidDestinationVector)
      .legalIf(isValidVectorMergeUnmergeOp(1, 0));

  getActionDefinitionsBuilder(G_CONCAT_VECTORS)
      .customIf([=](const LegalityQuery &Query) {
        const LLT &DstTy = Query.Types[0];
        const LLT &SrcTy = Query.Types[1];
        // Custom legalize concatenation of two 128-bit vectors into 256-bit
        // (128-bit vectors are not sub-registers of 256-bit vectors in AIE2P)
        return DstTy.isVector() && SrcTy.isVector() &&
               DstTy.getSizeInBits() == 256 && SrcTy.getSizeInBits() == 128;
      })
      .legalIf(isValidVectorMergeUnmergeOp(0, 1))
      .customIf([=](const LegalityQuery &Query) {
        const LLT &DstTy = Query.Types[0];
        const LLT &SrcTy = Query.Types[1];
        if (!DstTy.isVector() || !SrcTy.isVector())
          return false;

        // Concatenating vectors <= 64-bit are not sub-vector operations.
        // These should be lowered to insert vector elements.
        if (SrcTy.getSizeInBits() <= 64)
          return false;

        // Legalize concat vectors to have excatly two inputs
        return (DstTy.getNumElements() != 2 * SrcTy.getNumElements());
      });

  getActionDefinitionsBuilder(G_BUILD_VECTOR)
      // Legacy legalization for bitcasts
      .legalFor({{V2S32, S32}})
      // 64-bit vectors (e.g. the <8 x s8> bfp16 block-exponent) are register
      // types but have no native build-vector; custom-lower them by packing the
      // elements into a same-sized scalar and bitcasting. Handle this before the
      // general validity check below rejects 64-bit vectors.
      .customIf([=](const LegalityQuery &Query) {
        return Query.Types[0].isVector() &&
               Query.Types[0].getSizeInBits() == 64;
      })
      .unsupportedIf(IsNotValidDestinationVector)
      // We clamp the high values and not the low ones, sice the former
      // splits the values but the latter keeps the same G_BUILD_VECTOR in
      // the output instructions which causes an infinite loop since it
      // can't reach our custom legalization code.
      .clampMaxNumElements(0, S8, 64)
      .clampMaxNumElements(0, S16, 32)
      .clampMaxNumElements(0, S32, 16)
      .clampMaxNumElements(0, S64, 8)
      .custom();

  getActionDefinitionsBuilder(G_SHUFFLE_VECTOR)
      // Checks if the shuffle is "canonical", this enables additional actions
      // in the LLVM combiner and can change shuffle vectors legalization
      .lowerIf([=](const LegalityQuery &Query) {
        return Query.Types[0] == Query.Types[1];
      })
      .lower();

  getActionDefinitionsBuilder(G_JUMP_TABLE).custom();

  getActionDefinitionsBuilder(G_BRJT).custom();

  getActionDefinitionsBuilder(G_BRINDIRECT).legalFor({P0});

  // Variadic functions
  getActionDefinitionsBuilder(G_VASTART).custom();
  getActionDefinitionsBuilder(G_VAARG).custom();

  getLegacyLegalizerInfo().computeTables();
  verify(*ST.getInstrInfo());
}

bool AIE2PLegalizerInfo::legalizeCustom(
    LegalizerHelper &Helper, MachineInstr &MI,
    LostDebugLocObserver &LocObserver) const {
  switch (MI.getOpcode()) {
  default:
    break;
  case TargetOpcode::G_STORE:
    return AIEHelper.legalize_G_STORE(Helper, cast<GStore>(MI));
  case TargetOpcode::G_VASTART:
    return AIEHelper.legalizeG_VASTART(Helper, MI);
  case TargetOpcode::G_VAARG:
    return AIEHelper.legalizeG_VAARG(Helper, MI);
  case TargetOpcode::G_MEMSET:
  case TargetOpcode::G_MEMCPY:
  case TargetOpcode::G_MEMMOVE:
    return AIEHelper.legalizeMemCalls(Helper, MI, LocObserver);
  case TargetOpcode::G_BRJT:
    return AIEHelper.legalizeG_BRJT(Helper, MI);
  case TargetOpcode::G_FCONSTANT:
    return AIEHelper.legalizeG_FCONSTANT(Helper, MI);
  case TargetOpcode::G_JUMP_TABLE:
    return AIEHelper.legalizeG_JUMP_TABLE(Helper, MI);
  case TargetOpcode::G_DYN_STACKALLOC:
    return AIEHelper.legalizeG_DYN_STACKALLOC(Helper, MI);
  case TargetOpcode::G_EXTRACT_VECTOR_ELT:
    return AIEHelper.legalizeG_EXTRACT_VECTOR_ELT(Helper, MI);
  case TargetOpcode::G_INSERT_VECTOR_ELT:
    return AIEHelper.legalizeG_INSERT_VECTOR_ELT(Helper, MI);
  case TargetOpcode::G_FCMP:
    return AIEHelper.legalizeG_FCMP(Helper, MI, LocObserver);
  case TargetOpcode::G_FPTRUNC:
    return AIEHelper.legalizeG_FPTRUNC(Helper, MI);
  case TargetOpcode::G_FPEXT:
    return AIEHelper.legalizeG_FPEXT(Helper, MI);
  case TargetOpcode::G_FABS:
    return AIEHelper.legalizeG_FABS(Helper, MI);
  case TargetOpcode::G_FADD:
  case TargetOpcode::G_FSUB:
    return AIEHelper.legalizeG_FADD_G_FSUB(Helper, MI);
  case TargetOpcode::G_FMUL:
    return AIEHelper.legalizeG_FMUL(Helper, MI);
  case TargetOpcode::G_BUILD_VECTOR:
    return AIEHelper.legalizeG_BUILD_VECTOR(Helper, MI);
  case TargetOpcode::G_MERGE_VALUES:
    return AIEHelper.legalizeG_MERGE_VALUES(Helper, MI);
  case TargetOpcode::G_UNMERGE_VALUES:
    return AIEHelper.legalizeG_UNMERGE_VALUES(Helper, MI);
  case TargetOpcode::G_SEXT_INREG:
    return AIEHelper.legalizeG_SEXT_INREG(Helper, MI);
  case TargetOpcode::G_SELECT:
    return AIEHelper.legalizeG_SELECT(Helper, MI, /* MaxBitSize */ 512);
  case TargetOpcode::G_CONCAT_VECTORS:
    return AIEHelper.legalizeG_CONCAT_VECTORS(Helper, MI);
  case TargetOpcode::G_BITCAST:
    return AIEHelper.legalizeG_BITCAST(Helper, MI);
  case TargetOpcode::G_ADD:
  case TargetOpcode::G_SUB:
  case TargetOpcode::G_XOR:
    return AIEHelper.legalizeBinOp(Helper, MI);
  case TargetOpcode::G_TRUNC:
    return AIEHelper.legalizeG_TRUNC(Helper, MI);
  case TargetOpcode::G_ICMP:
    return AIEHelper.legalizeG_ICMP(Helper, cast<GICmp>(MI));
  }
  llvm_unreachable("Un-expected custom legalization");
}

bool AIE2PLegalizerInfo::legalizeIntrinsic(LegalizerHelper &Helper,
                                           MachineInstr &MI) const {

  // The loop_decrement is a bit of an exception in legalization since it
  // is an architecture-neutral intrinsic to implement hardware loops, not a
  // dedicated AIE intrinsic. As such it carries a boolean, which should be
  // legalized to a 32 bit integer type.
  switch (cast<GIntrinsic>(MI).getIntrinsicID()) {
  case Intrinsic::loop_decrement:
    return AIEHelper.legalizeLoopDecrement(Helper, MI);
  }

  return true;
}
